            let min_value = I256::try_from(100).unwrap();
            let max_value = I256::try_from(1000000000000i64).unwrap();
            let scaled_i256 = I256::try_from(scaled).unwrap();

            assert!(scaled_i256 > min_value);
            assert!(scaled_i256 < max_value);
        }
    }

